package app.alextran.immich.immersive

import kotlin.math.asin
import kotlin.math.atan2
import kotlin.math.cos
import kotlin.math.sin
import kotlin.math.sqrt
import kotlin.math.tan

/**
 * The outline of the photo itself on a panorama Immuch360 generated around it (design-final 2026-10-27, section 5,
 * point 3, lot P4): four arcs, the edges of the photo as its camera saw them, which the sphere of the immersive viewer
 * shows for a few seconds at the opening, with "Generated by AI beyond the photo's edges", so that what is true and
 * what is invented reads at a glance.
 *
 * The photo is where pano-v1 put it (make_pano_golden.py, step 1): a pinhole camera looking at [PhotoRegion.yaw] and
 * [PhotoRegion.pitch], whose plane meets a direction at (a, b), a to the right and b upwards, inside when |a| is at
 * most tan(hfov / 2) and |b| at most tan(vfov / 2). A straight edge of the photo is an arc of a great circle on the
 * sphere: the top edge of a wide photo bends up towards its middle.
 *
 * Directions are unit vectors in the frame of the panorama: x right, y up, z ahead, the centre column of the panorama
 * ahead, a longitude positive to the right. It is also the frame of the sphere of the viewer turned by its yaw, as long
 * as the skybox maps the centre column to +z of the Spatial SDK and does not mirror the image, what SKYBOX_YAW_DEGREES
 * stands for and the first session of MQ checks with a marked 360° photo. The mesh is a ribbon a little wide on each
 * side of the arcs, a light one at [RADIUS_M] over a wider dark one at [DARK_RADIUS_M], in front of the half sphere
 * (300 m) and of the skybox (950 m, ToolkitFeature of SDK 0.14.0), drawn by a TriangleMesh of the viewer with an unlit
 * material, double sided.
 *
 * Pure JVM, tested by PanoramaOutlineTest.
 */
internal object PanoramaOutline {
  /** Segments of each arc */
  const val SEGMENTS = 32

  /** Distance of the light ribbon from the eye, in metres */
  const val RADIUS_M = 240f

  /** Width of the light ribbon, in degrees seen from the eye: about 1.3 m at 240 m */
  const val WIDTH_DEGREES = 0.3

  /**
   * The dark ribbon behind the light one, wider, so that the outline shows on a bright sky as on a dark wall: black
   * and white read the same whatever the order of the channels of the colours of the vertices
   */
  const val DARK_RADIUS_M = 260f
  const val DARK_WIDTH_DEGREES = 0.7
  const val LIGHT = -1
  const val DARK = 0xFF000000.toInt()

  /** Vertices and indices of one ribbon: two vertices per point of an arc, two triangles per segment */
  const val RIBBON_VERTICES = 4 * (SEGMENTS + 1) * 2
  const val RIBBON_INDICES = 4 * SEGMENTS * 6

  /** Vertices and indices of the mesh of the viewer: the dark ribbon, then the light one */
  const val VERTICES = 2 * RIBBON_VERTICES
  const val INDICES = 2 * RIBBON_INDICES

  /**
   * The direction of the point (a, b) of the plane of the photo of [region], a and b in tangents: the centre of the
   * photo is (0, 0), its right edge a = tan(hfov / 2), its top edge b = tan(vfov / 2)
   */
  fun direction(region: PhotoRegion, a: Double, b: Double): DoubleArray {
    val yaw = Math.toRadians(region.yaw)
    val pitch = Math.toRadians(region.pitch)
    // The centre of the photo, the way to its right (along the longitude), the way to its top (along the meridian)
    val forward = doubleArrayOf(cos(pitch) * sin(yaw), sin(pitch), cos(pitch) * cos(yaw))
    val right = doubleArrayOf(cos(yaw), 0.0, -sin(yaw))
    val up = doubleArrayOf(-sin(pitch) * sin(yaw), cos(pitch), -sin(pitch) * cos(yaw))
    return normalize(DoubleArray(3) { forward[it] + a * right[it] + b * up[it] })
  }

  /** The four corners of the photo of [region]: top left, top right, bottom right, bottom left */
  fun corners(region: PhotoRegion): List<DoubleArray> {
    val t = tan(Math.toRadians(region.hfov) / 2)
    val s = tan(Math.toRadians(region.vfov) / 2)
    return listOf(-t to s, t to s, t to -s, -t to -s).map { (a, b) -> direction(region, a, b) }
  }

  /**
   * The four edges of the photo of [region], each from one corner of [corners] to the next: top, right, bottom, left,
   * [segments] + 1 directions each, evenly spaced on the plane of the photo
   */
  fun arcs(region: PhotoRegion, segments: Int = SEGMENTS): List<List<DoubleArray>> {
    val t = tan(Math.toRadians(region.hfov) / 2)
    val s = tan(Math.toRadians(region.vfov) / 2)
    val plane = listOf(-t to s, t to s, t to -s, -t to -s)
    return (0 until 4).map { k ->
      val (a0, b0) = plane[k]
      val (a1, b1) = plane[(k + 1) % 4]
      (0..segments).map { i ->
        val f = i.toDouble() / segments
        direction(region, a0 + (a1 - a0) * f, b0 + (b1 - b0) * f)
      }
    }
  }

  /** The longitude (from -180 to 180, positive to the right) and the latitude (positive upwards) of [d], in degrees */
  fun longitudeLatitude(d: DoubleArray): Pair<Double, Double> =
    Math.toDegrees(atan2(d[0], d[2])) to Math.toDegrees(asin(d[1].coerceIn(-1.0, 1.0)))

  /**
   * The ribbon along the arcs of [region]: for each point of an arc, a vertex [widthDegrees] / 2 to each side of the
   * edge, at [radius] from the eye (3 floats a vertex, arc after arc), and two triangles per segment
   */
  fun ribbon(
    region: PhotoRegion,
    radius: Float = RADIUS_M,
    widthDegrees: Double = WIDTH_DEGREES,
    segments: Int = SEGMENTS,
  ): OutlineRibbon {
    val arcs = arcs(region, segments)
    val half = tan(Math.toRadians(widthDegrees) / 2)
    val positions = FloatArray(4 * (segments + 1) * 2 * 3)
    val indices = IntArray(4 * segments * 6)
    var vertex = 0
    var index = 0
    for (arc in arcs) {
      val first = vertex
      for ((i, point) in arc.withIndex()) {
        // Along the arc, then across it on the sphere
        val before = arc[maxOf(i - 1, 0)]
        val after = arc[minOf(i + 1, arc.size - 1)]
        val along = DoubleArray(3) { after[it] - before[it] }
        val across = normalize(cross(point, along))
        for (side in doubleArrayOf(1.0, -1.0)) {
          val p = normalize(DoubleArray(3) { point[it] + side * half * across[it] })
          for (c in 0 until 3) positions[3 * vertex + c] = (p[c] * radius).toFloat()
          vertex++
        }
      }
      for (i in 0 until segments) {
        val v = first + 2 * i
        intArrayOf(v, v + 1, v + 2, v + 1, v + 3, v + 2).copyInto(indices, index)
        index += 6
      }
    }
    return OutlineRibbon(positions, indices)
  }

  /**
   * The mesh of the viewer for the photo of [region]: the dark ribbon, then the light one in front of it, with the
   * colour of each vertex
   */
  fun mesh(region: PhotoRegion): OutlineMesh {
    val dark = ribbon(region, DARK_RADIUS_M, DARK_WIDTH_DEGREES)
    val light = ribbon(region, RADIUS_M, WIDTH_DEGREES)
    val indices = IntArray(INDICES)
    dark.indices.copyInto(indices, 0)
    for (i in light.indices.indices) indices[RIBBON_INDICES + i] = light.indices[i] + RIBBON_VERTICES
    return OutlineMesh(
      positions = dark.positions + light.positions,
      colors = IntArray(VERTICES) { if (it < RIBBON_VERTICES) DARK else LIGHT },
      indices = indices,
    )
  }

  private fun cross(a: DoubleArray, b: DoubleArray): DoubleArray =
    doubleArrayOf(a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0])

  private fun normalize(v: DoubleArray): DoubleArray {
    val length = sqrt(v[0] * v[0] + v[1] * v[1] + v[2] * v[2])
    return DoubleArray(3) { v[it] / length }
  }
}

/** A ribbon of the outline: [positions], 3 floats a vertex, and [indices], 3 per triangle */
internal class OutlineRibbon(val positions: FloatArray, val indices: IntArray)

/** The mesh of the outline in the viewer: [positions], 3 floats a vertex, the colour of each, [indices] */
internal class OutlineMesh(val positions: FloatArray, val colors: IntArray, val indices: IntArray)
